import{A as e,d as t,p as n}from"./vendor~app~SearchBox~404.html~002.vitpress-theme~001.vuepress-theme~002.compile-lede-firmwa~lyho511h-CcSCa4je.js";import{oi as r}from"./common-YVe_mbL9.js";var i=JSON.parse(`{"path":"/tool/note/4gfe35bu/","title":"OpenCode Token 消费规则 | Note","lang":"zh-CN","frontmatter":{"title":"OpenCode Token 消费规则","createTime":"2026/08/30 15:30:48","permalink":"/tool/note/4gfe35bu/"},"readingTime":{"minutes":4.37,"words":1312},"git":{},"filePathRelative":"tool/note/003.opencode-token-consumption.md","headers":[]}`),a={name:`003.opencode-token-consumption.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>OpenCode 提供 Go 订阅与 Zen 按量付费两种消费模式，并有一批免费限免模型。本文整理各模式的计费方式、模型单价、请求量估算与省钱建议，数据来自 OpenCode 官方文档（2026 年 8 月）。模型与价格可能随官方调整而变化。</p><h2 id="一、消费体系总览" tabindex="-1"><a class="header-anchor" href="#一、消费体系总览"><span>一、消费体系总览</span></a></h2><table><thead><tr><th>模式</th><th>计费方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>Go 订阅</strong></td><td>月费 $10，按美元额度扣除</td><td>包含约 $60 额度（6 倍回报）</td></tr><tr><td><strong>Zen 按量付费</strong></td><td>按 token 实际消耗扣费</td><td>充值余额，用多少扣多少</td></tr><tr><td><strong>免费模型</strong></td><td>不扣费</td><td>限免活动，有次数/频率限制</td></tr></tbody></table><h2 id="二、go-订阅消费规则" tabindex="-1"><a class="header-anchor" href="#二、go-订阅消费规则"><span>二、Go 订阅消费规则</span></a></h2><h3 id="基础信息" tabindex="-1"><a class="header-anchor" href="#基础信息"><span>基础信息</span></a></h3><ul><li><strong>月费</strong>：$10（首月 $5 优惠，不定期）</li><li><strong>额度目标</strong>：$10 月费对应约 $60 的 token 消费额度（6 倍回报）</li><li><strong>可选</strong>：启用 <code>Use balance</code> 后，额度用尽可自动切换到 Zen 余额</li></ul><h3 id="额度周期限制" tabindex="-1"><a class="header-anchor" href="#额度周期限制"><span>额度周期限制</span></a></h3><table><thead><tr><th>周期</th><th>额度上限</th></tr></thead><tbody><tr><td>5 小时</td><td>$12</td></tr><tr><td>每周</td><td>$30</td></tr><tr><td>每月</td><td>$60</td></tr></tbody></table><h3 id="token-计算方式" tabindex="-1"><a class="header-anchor" href="#token-计算方式"><span>Token 计算方式</span></a></h3><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>消耗金额 = (输入 token 数 x 输入单价 + 输出 token 数 x 输出单价 + 缓存读取数 x 缓存单价) / 1,000,000</span></span></code></pre></div><p>不同模型单价不同，便宜模型能打更多次。</p><h2 id="三、各模型-token-单价-每-1m-tokens" tabindex="-1"><a class="header-anchor" href="#三、各模型-token-单价-每-1m-tokens"><span>三、各模型 Token 单价（每 1M tokens）</span></a></h2><h3 id="go-订阅模型" tabindex="-1"><a class="header-anchor" href="#go-订阅模型"><span>Go 订阅模型</span></a></h3><table><thead><tr><th>模型</th><th>Input</th><th>Output</th><th>Cached Read</th><th>Cached Write</th></tr></thead><tbody><tr><td>Kimi K3</td><td>$3.00</td><td>$15.00</td><td>$0.30</td><td>-</td></tr><tr><td>Grok 4.6 (&lt;=200K)</td><td>$2.00</td><td>$6.00</td><td>$0.50</td><td>-</td></tr><tr><td>Grok 4.6 (&gt;200K)</td><td>$4.00</td><td>$12.00</td><td>$1.00</td><td>-</td></tr><tr><td>Qwen3.8 Max</td><td>$2.00</td><td>$6.00</td><td>$0.25</td><td>$2.50</td></tr><tr><td>Qwen3.7 Max</td><td>$2.50</td><td>$7.50</td><td>$0.50</td><td>$3.125</td></tr><tr><td>GLM-5.3</td><td>$1.40</td><td>$4.40</td><td>$0.26</td><td>-</td></tr><tr><td>GLM-5.2</td><td>$1.40</td><td>$4.40</td><td>$0.26</td><td>-</td></tr><tr><td>GLM-5.1</td><td>$1.40</td><td>$4.40</td><td>$0.26</td><td>-</td></tr><tr><td>Kimi K2.7 Code</td><td>$0.95</td><td>$4.00</td><td>$0.19</td><td>-</td></tr><tr><td>Kimi K2.6</td><td>$0.95</td><td>$4.00</td><td>$0.16</td><td>-</td></tr><tr><td>Qwen3.6 Plus (&gt;256K)</td><td>$2.00</td><td>$6.00</td><td>$0.20</td><td>$2.50</td></tr><tr><td>Qwen3.7 Plus (&gt;256K)</td><td>$1.20</td><td>$4.80</td><td>$0.12</td><td>$1.50</td></tr><tr><td>DeepSeek V4 Pro (Peak)</td><td>$1.32</td><td>$3.96</td><td>$0.044</td><td>-</td></tr><tr><td>DeepSeek V4 Pro (Off-Peak)</td><td>$0.66</td><td>$1.98</td><td>$0.022</td><td>-</td></tr><tr><td>Hy4 preview</td><td>$0.834</td><td>$2.501</td><td>$0.042</td><td>-</td></tr><tr><td>MiMo-V2.5-Pro</td><td>$0.435</td><td>$0.87</td><td>$0.003625</td><td>-</td></tr><tr><td>GPT 5.6 Luna (&gt;272K)</td><td>$0.40</td><td>$1.80</td><td>$0.04</td><td>$0.50</td></tr><tr><td>GPT 5.6 Luna (&lt;=272K)</td><td>$0.20</td><td>$1.20</td><td>$0.02</td><td>$0.25</td></tr><tr><td>Qwen3.6 Plus (&lt;=256K)</td><td>$0.50</td><td>$3.00</td><td>$0.05</td><td>$0.625</td></tr><tr><td>Qwen3.7 Plus (&lt;=256K)</td><td>$0.40</td><td>$1.60</td><td>$0.04</td><td>$0.50</td></tr><tr><td>LongCat-2.0</td><td>$0.30</td><td>$1.20</td><td>$0.006</td><td>-</td></tr><tr><td>MiniMax M3</td><td>$0.30</td><td>$1.20</td><td>$0.06</td><td>-</td></tr><tr><td>MiniMax M2.7</td><td>$0.30</td><td>$1.20</td><td>$0.06</td><td>$0.375</td></tr><tr><td>DeepSeek V4 Flash (Peak)</td><td>$0.44</td><td>$1.32</td><td>$0.014</td><td>-</td></tr><tr><td>DeepSeek V4 Flash (Off-Peak)</td><td>$0.22</td><td>$0.66</td><td>$0.007</td><td>-</td></tr><tr><td>Hy3</td><td>$0.14</td><td>$0.58</td><td>$0.035</td><td>-</td></tr><tr><td>GLM-5.3-Flash</td><td>$0.15</td><td>$0.50</td><td>$0.03</td><td>-</td></tr><tr><td>Qwen3.8 Flash</td><td>$0.15</td><td>$0.47</td><td>$0.016</td><td>$0.20</td></tr><tr><td>MiMo-V2.5</td><td>$0.14</td><td>$0.28</td><td>$0.0028</td><td>-</td></tr><tr><td>Muse Spark 1.2 Contributor</td><td>$0.10</td><td>$0.20</td><td>$0.002</td><td>-</td></tr></tbody></table><h3 id="zen-免费模型" tabindex="-1"><a class="header-anchor" href="#zen-免费模型"><span>Zen 免费模型</span></a></h3><table><thead><tr><th>模型</th><th>Input</th><th>Output</th><th>说明</th></tr></thead><tbody><tr><td>Big Pickle</td><td>Free</td><td>Free</td><td>限免，数据可能用于训练</td></tr><tr><td>MiMo-V2.5 Free</td><td>Free</td><td>Free</td><td>限免，数据可能用于训练</td></tr><tr><td>Ling 3.0 Flash Fin Free</td><td>Free</td><td>Free</td><td>限免</td></tr><tr><td>Nemotron 3 Ultra Free</td><td>Free</td><td>Free</td><td>NVIDIA 免费端点，Trial 用途</td></tr><tr><td>Nemotron 3.5 Lightning Free</td><td>Free</td><td>Free</td><td>NVIDIA 免费端点，Trial 用途</td></tr><tr><td>Muse Spark 1.2 Contributor Free</td><td>Free</td><td>Free</td><td>限免，Meta 用于训练</td></tr></tbody></table><h2 id="四、每-5-小时可请求数-排序" tabindex="-1"><a class="header-anchor" href="#四、每-5-小时可请求数-排序"><span>四、每 5 小时可请求数（排序）</span></a></h2><p>按官方估算基准（典型请求模式）：</p><table><thead><tr><th>排名</th><th>模型</th><th>5h 请求数</th><th>周请求数</th><th>月请求数</th></tr></thead><tbody><tr><td>1</td><td>Muse Spark 1.2 Contributor</td><td>45,300</td><td>113,300</td><td>226,600</td></tr><tr><td>2</td><td>MiMo-V2.5</td><td>30,100</td><td>75,200</td><td>150,400</td></tr><tr><td>3</td><td>LongCat-2.0</td><td>11,400</td><td>28,600</td><td>57,200</td></tr><tr><td>4</td><td>DeepSeek V4 Flash</td><td>7,600</td><td>18,900</td><td>37,800</td></tr><tr><td>5</td><td>Qwen3.8 Flash</td><td>5,400</td><td>13,500</td><td>27,000</td></tr><tr><td>6</td><td>Hy3</td><td>4,300</td><td>10,750</td><td>21,500</td></tr><tr><td>7</td><td>Qwen3.7 Plus</td><td>4,300</td><td>10,800</td><td>21,600</td></tr><tr><td>8</td><td>MiMo-V2.5-Pro</td><td>3,250</td><td>8,150</td><td>16,300</td></tr><tr><td>9</td><td>MiniMax M2.7</td><td>3,400</td><td>8,500</td><td>17,000</td></tr><tr><td>10</td><td>MiniMax M3</td><td>3,200</td><td>8,000</td><td>16,000</td></tr><tr><td>11</td><td>GPT 5.6 Luna</td><td>2,050</td><td>5,100</td><td>10,250</td></tr><tr><td>12</td><td>GLM-5.3-Flash</td><td>1,580</td><td>3,950</td><td>7,900</td></tr><tr><td>13</td><td>Kimi K2.7 Code</td><td>1,350</td><td>3,380</td><td>6,750</td></tr><tr><td>14</td><td>Hy4 preview</td><td>1,350</td><td>3,380</td><td>6,770</td></tr><tr><td>15</td><td>Kimi K2.6</td><td>1,150</td><td>2,880</td><td>5,750</td></tr><tr><td>16</td><td>DeepSeek V4 Pro</td><td>1,050</td><td>2,600</td><td>5,200</td></tr><tr><td>17</td><td>GLM-5.2</td><td>880</td><td>2,150</td><td>4,300</td></tr><tr><td>18</td><td>GLM-5.1</td><td>880</td><td>2,150</td><td>4,300</td></tr><tr><td>19</td><td>Qwen3.7 Max</td><td>340</td><td>840</td><td>1,690</td></tr><tr><td>20</td><td>GLM-5.3</td><td>220</td><td>540</td><td>1,080</td></tr><tr><td>21</td><td>Qwen3.8 Max</td><td>160</td><td>400</td><td>810</td></tr><tr><td>22</td><td>Grok 4.6</td><td>169</td><td>423</td><td>845</td></tr><tr><td>23</td><td>Kimi K3</td><td>110</td><td>250</td><td>490</td></tr></tbody></table><h3 id="消费等级-从省到费" tabindex="-1"><a class="header-anchor" href="#消费等级-从省到费"><span>消费等级（从省到费）</span></a></h3><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>最省                                          最费</span></span>
<span class="line"><span>Muse 1.2 &gt; MiMo-V2.5 &gt; LongCat-2.0 &gt; DeepSeek V4 Flash &gt; Qwen3.8 Flash</span></span>
<span class="line"><span>&gt; Hy3 &gt; Qwen3.7 Plus &gt; MiMo-V2.5-Pro &gt; MiniMax M3 &gt; Kimi K2.6/2.7</span></span>
<span class="line"><span>&gt; DeepSeek V4 Pro &gt; GLM-5.2/5.1 &gt; GPT 5.6 Luna &gt; GLM-5.3-Flash</span></span>
<span class="line"><span>&gt; GLM-5.3 &gt; Qwen3.7 Max &gt; Qwen3.8 Max &gt; Grok 4.6 &gt; Kimi K3</span></span></code></pre></div><h2 id="五、影响消费的关键因素" tabindex="-1"><a class="header-anchor" href="#五、影响消费的关键因素"><span>五、影响消费的关键因素</span></a></h2><h3 id="_5-1-上下文长度" tabindex="-1"><a class="header-anchor" href="#_5-1-上下文长度"><span>5.1 上下文长度</span></a></h3><ul><li>上下文越长，输入 token 数越多，消耗越大</li><li>部分模型在超长上下文时单价翻倍（Grok 4.6、GPT 5.6 Luna、Qwen3.6/3.7 Plus、DeepSeek V4 Pro/Flash）</li></ul><h3 id="_5-2-高峰-低谷-deepseek-专属" tabindex="-1"><a class="header-anchor" href="#_5-2-高峰-低谷-deepseek-专属"><span>5.2 高峰/低谷（DeepSeek 专属）</span></a></h3><table><thead><tr><th>时段</th><th>类型</th></tr></thead><tbody><tr><td>01:00-04:00 UTC、06:00-10:00 UTC（周一至周五）</td><td>Peak（高价）</td></tr><tr><td>其他时段 + 周末</td><td>Off-Peak（低价）</td></tr></tbody></table><h3 id="_5-3-缓存命中" tabindex="-1"><a class="header-anchor" href="#_5-3-缓存命中"><span>5.3 缓存命中</span></a></h3><ul><li><strong>Cached Read</strong>：相同上下文再次请求时，缓存部分按更低价计费</li><li><strong>Cached Write</strong>：首次缓存写入时按较低价计费</li><li>缓存命中率越高，实际消费越低</li></ul><h3 id="_5-4-模型选择" tabindex="-1"><a class="header-anchor" href="#_5-4-模型选择"><span>5.4 模型选择</span></a></h3><ul><li>同一任务用便宜模型（如 MiMo-V2.5）比贵模型（如 Kimi K3）消耗低几十倍</li><li>贵模型不一定适合所有任务，轻量任务选便宜模型更划算</li></ul><h2 id="六、消费管理" tabindex="-1"><a class="header-anchor" href="#六、消费管理"><span>六、消费管理</span></a></h2><h3 id="查看用量" tabindex="-1"><a class="header-anchor" href="#查看用量"><span>查看用量</span></a></h3><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>opencode    # 在 TUI 中运行</span></span>
<span class="line"><span>/connect    # 连接账户</span></span>
<span class="line"><span>/auth       # 登录查看详细用量</span></span></code></pre></div><h3 id="设置月度限额" tabindex="-1"><a class="header-anchor" href="#设置月度限额"><span>设置月度限额</span></a></h3><p>在 Zen 控制台中设置整月用量上限，到上限后自动停止消费。</p><h3 id="省钱建议" tabindex="-1"><a class="header-anchor" href="#省钱建议"><span>省钱建议</span></a></h3><ol><li><strong>默认用便宜模型</strong>：日常编码用 MiMo-V2.5、LongCat-2.0 等</li><li><strong>复杂任务切贵模型</strong>：重度重构/架构时用 Kimi K3、Qwen3.8 Max</li><li><strong>利用缓存</strong>：保持上下文一致性，提高 Cached Read 命中率</li><li><strong>选对时段</strong>：DeepSeek 模型在 Off-Peak 时段半价</li><li><strong>Go 额度用完</strong>：用 Zen 免费模型继续工作</li></ol><div class="hint-container note"><p class="hint-container-title">笔记</p><p>数据来源：OpenCode 官方文档，2026 年 8 月。模型和价格可能随官方调整而变化。详见：<a href="https://opencode.ai/docs/go/" target="_blank" rel="noopener noreferrer">https://opencode.ai/docs/go/</a> 与 <a href="https://opencode.ai/docs/zen/" target="_blank" rel="noopener noreferrer">https://opencode.ai/docs/zen/</a>。</p></div>`,39)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};